// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airDrop} from "../src/airDrop.sol";

contract InvMutTest is Test {
    airDrop c;
    function setUp() public { c = new airDrop(); }

    // Fuzz parameters: the `from` address, a uint value v, uint decimals, and a flag controlling callee behavior
    // We must deploy an adversarial callee that performs a state change inside transferFrom when instructed.
    function testFuzz_property(address from, uint256 v, uint256 decimals, bool doStateChange) public {
        // Keep decimals reasonable to avoid overflow in v * 10**decimals
        decimals = bound(decimals, 0, 18);
        // Keep v small enough so multiplication doesn't overflow 256-bit (with decimals <=18 this is safe)
        v = bound(v, 0, type(uint256).max / (10 ** decimals == 0 ? 1 : 10 ** decimals));

        // Deploy adversarial callee that implements transferFrom and optionally mutates its own state
        AdversarialCallee adv = new AdversarialCallee(doStateChange);

        // Prepare single-recipient array to keep observations simple
        address[] memory tos = new address[](1);
        tos[0] = address(0xBEEF);

        bool ok;
        // call transfer and capture whether it succeeded (reference C should succeed when callee does not revert; it will also succeed when callee mutates state because call allows state change)
        try c.transfer(from, address(adv), tos, v, decimals) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for any inputs, if the callee's transferFrom does NOT revert when executed (i.e., it returns normally even if it mutates state),
        // the reference C (using call) will succeed and return true. The mutant using staticcall will fail when the callee tries to mutate state.
        // Our adversarial callee: when doStateChange==true it performs a state write inside transferFrom; when false it does not.
        // So for the reference contract (P) the call should succeed in BOTH cases (it invokes the callee and lets it mutate state). However, the mutant (M)
        // using staticcall would cause the invocation to fail when doStateChange==true. We express the universal property that the reference should
        // succeed (ok==true) for both behaviors of the callee; this will hold for the reference C, and the mutant will fail when doStateChange==true.

        // Assert that the reference C succeeds for the deployed adversarial callee regardless of whether it mutates state.
        // (This is the single assertion reading c's observable behavior via the success of the external call.)
        assertTrue(ok);
    }
}

// Adversarial callee that exposes transferFrom(address,address,uint256).
// When shouldMutate==true it performs a state change (incrementing a counter) inside transferFrom.
// When shouldMutate==false it does not change state and simply returns true.
contract AdversarialCallee {
    uint256 public counter;
    bool public shouldMutate;

    constructor(bool _shouldMutate) {
        shouldMutate = _shouldMutate;
        counter = 0;
    }

    // Must match selector: transferFrom(address,address,uint256)
    function transferFrom(address /*from*/, address /*to*/, uint256 /*value*/) external returns (bool) {
        if (shouldMutate) {
            // state change that staticcall would forbid
            counter += 1;
        }
        return true;
    }
}
